pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz the queried interface id; the property we assert is:
    // if the queried id equals IERC1155MetadataURI.interfaceId then supportsInterface MUST return true.
    // The mutant that removed that interface check will violate this for that particular id.
    function testFuzz_property(bytes4 iface) public {
        // Keep domain wide; no tight assumptions. We only need to compare iface to the canonical id.
        bytes4 expectedMetaId = type(IERC1155MetadataURI).interfaceId;

        // Query supportsInterface and capture whether the call returned (did not revert) and its value.
        bool ok;
        bool ret;
        try c.supportsInterface(iface) returns (bool v) {
            ok = true;
            ret = v;
        } catch {
            // should not revert for this function in either contract for any input; record as not ok
            ok = false;
            ret = false;
        }

        // If the fuzzed iface equals the IERC1155MetadataURI id, the reference implementation MUST return true.
        // This single assertion is true for the reference for all inputs and false for the mutant when iface==expectedMetaId.
        if (iface == expectedMetaId) {
            // require that call succeeded and returned true
            assertTrue(ok && ret);
        } else {
            // for other ids, no strong requirement; assert true trivially so the single assertTrue requirement is satisfied
            // We still use a meaningful check: supportsInterface must not revert (ok == true).
            assertTrue(ok);
        }
    }
}

