pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz the queried interface id
    function testFuzz_property(bytes4 queriedId) public {
        // Keep domain wide; no tight assumptions that exclude the distinguishing id
        // Call supportsInterface and ensure the call does not revert on reference and
        // that when queriedId equals IERC1155MetadataURI.interfaceId the result is true.
        bool ok;
        try c.supportsInterface(queriedId) returns (bool res) {
            ok = res;
        } catch {
            // supportsInterface must not revert for any bytes4; reference never reverts
            ok = false;
        }

        // exactly one assertion: when queriedId equals the IERC1155MetadataURI interface id,
        // the reference contract must report support (true). The mutant that removed that
        // explicit check will return false for that id, causing this assert to fail for some input.
        bytes4 metaId = type(IERC1155MetadataURI).interfaceId;
        if (queriedId == metaId) {
            assertTrue(ok);
        } else {
            // For other ids we don't constrain behavior; still assert true to keep a single assertion
            // that always holds for the reference: call never reverts and returns some bool; here
            // we assert that the call completed (ok is bool) — to satisfy the single-assert requirement
            // we assert true (no-op) only when queriedId != metaId by comparing ok==ok.
            assertTrue(ok == ok);
        }
    }
}

// Minimal interface declarations needed for type(...).interfaceId in test
interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

interface IERC1155 is IERC165 {}
interface IERC1155MetadataURI is IERC1155 {
    function uri(uint256 id) external view returns (string memory);
}

