pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz the queried interface id so the fuzzer can choose the canonical IERC1155MetadataURI id
    function testFuzz_property(bytes4 interfaceId) public {
        // keep domain wide: no vm.assume so fuzzer can pick any bytes4, including the IERC1155MetadataURI id

        // call supportsInterface and record whether it returns true (no revert expected)
        bool ok;
        try c.supportsInterface(interfaceId) returns (bool r) {
            ok = r;
        } catch {
            // should not revert for any bytes4; treat revert as failure
            ok = false;
        }

        // The universal property we assert: when the fuzzer picks the IERC1155MetadataURI id,
        // the correct reference contract C must return true. The mutant that removed the
        // explicit IERC1155MetadataURI check will return false for that id, so the test
        // will fail on the mutant for that input. We express this as a single assertTrue
        // by checking (interfaceId != type(IERC1155MetadataURI).interfaceId) || ok
        // which is equivalent to: if interfaceId equals the IERC1155MetadataURI id then ok must be true.
        assertTrue(interfaceId != type(IERC1155MetadataURI).interfaceId || ok);
    }
}

