pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzz the token id to find one that distinguishes the behavior on zero address.
    function testFuzz_property(uint256 tokenId) public {
        // keep tokenId within a wide but practical range
        uint256 id = tokenId;

        // The universal property we assert: calling balanceOf on the zero address MUST revert in the reference.
        // We observe behavior via try/catch and assert that the call DOES revert (i.e., ok == false).
        bool ok;
        try c.balanceOf(address(0), id) returns (uint256) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract always reverts for address(0) per its require; the mutant does not — so
        // this assertion holds for the reference for all ids, and will fail on the mutant for any id where
        // the mutant returns instead of reverting.
        assertTrue(!ok);
    }
}

