contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // We fuzz the tokenId and an arbitrary account address. The reference implementation
    // always returns the stored _balances[id][account] when calling balanceOf(account, id).
    // The mutant returns 0 for account==address(0) regardless of stored value. We let the
