pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // We fuzz the tokenId and an amount to trigger a stored non-zero balance for address(0).
    // General rule: for every (account, id) the view balanceOf(account,id) returns the stored balance backing that pair.
    // The mutant makes balanceOf(address(0), id) always return 0 regardless of stored balance. We therefore
    // exercise a scenario where the contract stores a non-zero balance for address(0) by using internal minting
    // operations exposed by the contract's _mint via public functions: C has createGameItem and mint that eventually
    // call _mint which stores balances; but C.mint requires msg.sender to have enough NRN and other conditions.
    // To force a stored balance for address(0) we will directly call the ERC1155._mint behavior by exploiting
    // that C.createGameItem emits and sets up items and then we can call burn with allowedBurningAddresses to
    // invoke _burn which reads balances; however burn requires allowedBurningAddresses[msg.sender]==true and then
    // _burn will reduce balance. Instead, a simpler way is to call C.createGameItem to create an item and then
    // directly call C._mint is not available. But we can rely on the constructor not having minted to address(0).
    // To create a stored non-zero balance for address(0) we instead use the public function setAllowedBurningAddresses
    // (to set this test contract) and then use the public burn that will attempt to burn from address(0) if that
    // balance was non-zero. However there is no public function to credit address(0) except through edge cases.
    // As the fuzz must not hardcode values, we will rely on the fact that the reference contract's balanceOf for
    // address(0) never reverts and returns whatever is stored, while the mutant returns 0 when account==address(0).
    // We'll assert that calling balanceOf(address(0), id) does not revert and that the returned value equals
    // calling balanceOf(address(0), id) via the contract (this is tautological). To create a distinguishing check,
    // we call balanceOf on address(0) and also on a copy obtained by calling a batch that includes address(0) via
    // balanceOfBatch: in the reference these two reflect the same stored value; the mutant still changes balanceOf
    // for address(0) only. We will assert that balanceOfBatch returns the same value for index corresponding to address(0)
    // as the scalar balanceOf. The mutant still returns 0 for balanceOf(address(0), id) but balanceOfBatch in mutant
    // will call balanceOf internally and thus also be 0 — so this would not distinguish. Therefore we must craft a
    // direct check: the reference allows creating a game item and then calling _mint to any address via the public mint
    // function. C.mint requires the caller to have NRN funds; however in setUp we used address(this) as treasury and owner.
    // We can instead call createGameItem to make an item and then, because the contract's mint function (C.mint)
    // performs an on-chain payment and calls _mint only on success, we cannot easily mint to address(0) via public API.
    // Given constraints, we take a different approach: the universal rule we assert is that calling balanceOf on any
    // account never reverts (the reference requires a revert only when account==address(0)). But in reference balanceOf
    // DOES revert for zero address (it has require(account != address(0))). The mutant changed it to not revert. So the
    // proper distinguishing property is inverted: the reference REVERTS for account==address(0) while mutant does not.
    // We therefore assert the reference's behavior that balanceOf(address(0), id) REVERTS (i.e. the call fails) for every id,
    // and the mutant will violate this by returning 0 instead of reverting for some input. This fits the change described
    // (inverted check). We fuzz tokenId to find such a case.
    function testFuzz_property(uint256 tokenId) public {
        // Keep tokenId within a wide but reasonable bound so array accesses in other calls won't revert.
        tokenId = bound(tokenId, 0, 10);

        // Call balanceOf(address(0), tokenId) catching revert vs success
        bool ok;
        try c.balanceOf(address(0), tokenId) returns (uint256 v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract requires a revert for address(0) (it has `require(account != address(0))`).
        // So for ALL admissible inputs the correct contract causes a revert (ok == false). The mutant changed
        // that behavior to return 0 (ok == true) for address(0) and thus will make this assertion fail for some input.
        assertTrue(!ok);
    }
}

