// Minimal fake neuron that C expects: balanceOf, approveSpender, transferFrom
contract FakeNeuron {
    mapping(address => uint256) public balances;
    function setBalance(address who, uint256 amt) public { balances[who] = amt; }
    function balanceOf(address who) external view returns (uint256) { return balances[who]; }
    function approveSpender(address account, uint256 amount) external {
        // do nothing; C expects this to succeed
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (balances[from] < amount) return false;
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }
}

