    function setBalance(address who, uint256 amt) public {
        balances[who] = amt;
    }
    function setAllowance(address owner, address spender, uint256 amt) public {
        allowed[owner][spender] = amt;
    }

    function balanceOf(address account) external view returns (uint256) {
        return balances[account];
    }

    function approveSpender(address account, uint256 amount) external {
        // noop for mock
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (allowed[from][msg.sender] < amount) return false;
        if (balances[from] < amount) return false;
        balances[from] -= amount;
        balances[to] += amount;
        allowed[from][msg.sender] -= amount;
        return true;
    }

    function allowance(address owner, address spender) external view returns (uint256) {
        return allowed[owner][spender];
    }
}

