// Minimal MockNeuron that provides the subset of Neuron API used by C
contract MockNeuron {
    mapping(address => uint256) public balances;
    mapping(address => mapping(address => uint256)) public allowances;

    function mint(address to, uint256 amount) external {
        balances[to] += amount;
    }

    function balanceOf(address account) external view returns (uint256) {
        return balances[account];
    }

    function approveSpender(address account, uint256 amount) external {
        // In original Neuron, approveSpender(account, amount) sets allowance[account][msg.sender]=amount
        allowances[account][msg.sender] = amount;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (balances[from] < amount) return false;
        // check allowance: allowance[from][msg.sender] must be >= amount
        if (allowances[from][msg.sender] < amount) return false;
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }

    // helpers to satisfy calls: hasRole etc. Not used by C.
}

