pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address a0, address a1, uint256 id0, uint256 id1) public {
        // keep addresses distinct and not zero to be meaningful owners
        vm.assume(a0 != address(0));
        vm.assume(a1 != address(0));
        // create two distinct ids (allow fuzzer to pick equal ids too; property still holds)
        // bound ids to reasonable small range to avoid out-of-gas in helper logic
        id0 = uint256(uint64(id0));
        id1 = uint256(uint64(id1));

        // prepare a simple scenario: create two game items so ids exist
        // make caller an admin so createGameItem can be called
        c.adjustAdminAccess(address(this), true);

        // create two game items; they will occupy ids 0 and 1 (or 0 twice if created with same params doesn't matter)
        c.createGameItem("item0", "uri0", false, true, 0, 0, 1);
        c.createGameItem("item1", "uri1", false, true, 0, 0, 1);

        // choose indices within bounds: map arbitrary id0,id1 into [0, allGameItemAttributes.length-1]
        uint256 len = c.uniqueTokensOutstanding();
        // ensure len > 0
        vm.assume(len > 0);
        uint256 idx0 = id0 % len;
        uint256 idx1 = id1 % len;

        // mint some tokens to a0 and a1 for corresponding ids
        // use impersonation to have contract mint (we are admin but mint is internal to ERC1155, use internal _mint via public mint function)
        // the contract exposes mint(tokenId, quantity) public, so call to mint tokens to msg.sender
        // we need tokens held by a0 and a1, so use vm.prank to make them call a helper function that mints to themselves

        // Make sure the contract has been instantiated with a Neuron address to avoid interactions elsewhere (not needed here)

        // mint token idx0 to a0
        vm.prank(address(this));
        c.mint(idx0, 5);
        // Now transfer minted tokens from this contract (msg.sender) to a0
        // The contract minted to address(this), so transfer from address(this) to a0
        // Use safeTransferFrom: since we are address(this), no approval needed
        vm.prank(address(this));
        c.safeTransferFrom(address(this), a0, idx0, 2, "");

        // mint token idx1 to this and transfer to a1
        vm.prank(address(this));
        c.mint(idx1, 7);
        vm.prank(address(this));
        c.safeTransferFrom(address(this), a1, idx1, 3, "");

        // Prepare inputs for balanceOfBatch: two accounts and two ids
        address[] memory accounts = new address[](2);
        uint256[] memory ids = new uint256[](2);
        accounts[0] = a0;
        accounts[1] = a1;
        ids[0] = idx0;
        ids[1] = idx1;

        // Call balanceOfBatch and individual balanceOf for each pair
        uint256[] memory batch = c.balanceOfBatch(accounts, ids);
        uint256 b0 = c.balanceOf(accounts[0], ids[0]);
        uint256 b1 = c.balanceOf(accounts[1], ids[1]);

        // The universal property: for any admissible inputs, batch[i] == balanceOf(accounts[i], ids[i])
        // This holds for the reference implementation for all inputs, and the mutant that uses ids[0] for every entry will fail when ids[0] != ids[1] and the balances differ.
        assertTrue(batch.length == 2 && batch[0] == b0 && batch[1] == b1);
    }
}

